examples.setupTemplate:
@State private var preferences = MonarchAppearancePreferences(
    scheme: {{preferences.theme|case}},
    contrast: {{preferences.contrast|case}},
    motion: {{preferences.motion|case}},
    density: {{preferences.density|case}}
)

examples.setup:
@State private var preferences = MonarchAppearancePreferences(
    scheme: .light,
    contrast: .system,
    motion: .system,
    density: .comfortable
)

@State private var preferences = MonarchAppearancePreferences(motion: .reduce)
@State private var isExpanded = false
@Environment(\.accessibilityReduceMotion) private var systemReducesMotion

examples.code:
VStack(alignment: .leading) {
    MonarchAppearancePanel(selection: $preferences, rows: [.motion])
    MonarchButton(isExpanded ? "Collapse" : "Expand") {
        if preferences.reducesMotion(systemReducesMotion: systemReducesMotion) {
            isExpanded.toggle()
        } else {
            withAnimation { isExpanded.toggle() }
        }
    }
}
